// Class 8 Social Science practice bank, part 2: India's Long Road to Independence to Cultural Currents: 13th to 17th Centuries (Exploring Society: India and Beyond).
StudyData.addPractice(8, "sst", {
  "indias-long-road-to-independence": {
    mcq: [
      { q: "The Indian National Congress was founded in", options: ["1857", "1885", "1905", "1919"], answer: 1, explain: "The Indian National Congress was founded in 1885. The Partition of Bengal was in 1905 and the Jallianwala Bagh massacre in 1919.", level: 1 },
      { q: "The call 'Do or Die' is linked with which movement?", options: ["Non-Cooperation Movement", "Swadeshi movement", "Civil Disobedience Movement", "Quit India Movement"], answer: 3, explain: "'Do or Die' was the call of the Quit India Movement, which began on 8 August 1942.", level: 1 },
      { q: "At which place did the Congress demand Purna Swaraj in 1929?", options: ["Amritsar", "Champaran", "Lahore", "Dandi"], answer: 2, explain: "The Congress demanded complete independence (Purna Swaraj) at its Lahore session in 1929.", level: 1 },
      { q: "Mahatma Gandhi returned to India from South Africa in", options: ["1885", "1930", "1942", "1915"], answer: 3, explain: "Gandhi returned to India in 1915. His first major satyagraha in India was at Champaran in 1917.", level: 1 },
      { q: "Who formed the Indian National Army (INA)?", options: ["Subhas Chandra Bose", "Bal Gangadhar Tilak", "Gopal Krishna Gokhale", "Jawaharlal Nehru"], answer: 0, explain: "Subhas Chandra Bose formed the INA to fight for India's freedom.", level: 1 },
      { q: "Why did many Indians feel angry about the Rowlatt Act of 1919?", options: ["It raised the price of salt", "It divided Bengal into two parts", "It allowed people to be held without a proper trial", "It banned Indian-made cloth"], answer: 2, explain: "The Rowlatt Act allowed the government to detain people without a fair trial. The salt law was the target of the Dandi March and the division of Bengal was in 1905.", level: 2 },
      { q: "Which of these is an example of the Swadeshi spirit?", options: ["Choosing locally made cloth instead of imported cloth", "Paying the salt tax on time", "Joining the colonial army", "Buying only foreign goods"], answer: 0, explain: "Swadeshi means using goods made in one's own country and boycotting foreign ones.", level: 2 },
      { q: "A school group in 1905 decides to wear only cloth woven in India and to refuse mill cloth from abroad.\nWhich idea are they following?", options: ["Satyagraha at Champaran", "Boycott and Swadeshi", "The Quit India call", "Purna Swaraj at Lahore"], answer: 1, explain: "Refusing foreign goods is boycott, and choosing Indian-made goods is Swadeshi. Both rose after the Partition of Bengal in 1905.", level: 2 },
      { q: "On a map of India, the Dandi March ended at a village on the coast of which sea?", options: ["Bay of Bengal", "Indian Ocean near Kanyakumari", "Gulf of Mannar", "Arabian Sea"], answer: 3, explain: "Dandi lies on the Gujarat coast, which faces the Arabian Sea. The march started inland near Ahmedabad and ended at the sea, where Gandhi broke the salt law.", level: 2 },
      { q: "Assertion (A): Gandhi chose the salt law for a protest in 1930.\nReason (R): Salt was used in every household, so the tax affected rich and poor alike.", options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."], answer: 0, explain: "Both are true. Because salt was needed by everyone, a protest against the salt law could unite people across the country, so R explains A.", level: 2, keepOrder: true },
      { q: "Which list gives these events in the correct time order?", options: ["Dandi March, Partition of Bengal, Quit India, Jallianwala Bagh", "Jallianwala Bagh, Partition of Bengal, Dandi March, Quit India", "Partition of Bengal, Jallianwala Bagh, Dandi March, Quit India", "Quit India, Dandi March, Jallianwala Bagh, Partition of Bengal"], answer: 2, explain: "The Partition of Bengal was in 1905, Jallianwala Bagh in 1919, the Dandi March in 1930 and Quit India in 1942.", level: 3 },
      { q: "Which pair is correctly matched?", options: ["Purna Swaraj demand - Lahore session, 1929", "Dandi March - 1942", "Swadeshi movement - Rowlatt Act", "Non-Cooperation Movement - 1905"], answer: 0, explain: "The Purna Swaraj demand was made at Lahore in 1929. The Dandi March was in 1930, Swadeshi followed the Partition of Bengal and Non-Cooperation ran from 1920 to 1922.", level: 3 },
      { q: "A student says, 'India got independence in 1947, so our Constitution also began in 1947.'\nWhich reply is correct?", options: ["The Constitution came into force in 1930", "The Constitution came into force on 26 January 1950, a little over two years after independence", "The Constitution was adopted on 15 August 1947", "India had no Constitution until 1960"], answer: 1, explain: "India became independent on 15 August 1947 and the Constitution came into force on 26 January 1950, which is celebrated as Republic Day.", level: 3 },
      { q: "Why is the Swadeshi movement seen as both an economic and a political protest?", options: ["It only asked people to pay more taxes", "It was fought only in law courts", "It ended British rule in 1905", "Boycotting foreign goods hurt British trade and also showed the people's anger at a government decision"], answer: 3, explain: "Boycott reduced the sale of foreign goods, which was economic pressure, and it was also a public protest against the Partition of Bengal, which was political.", level: 3 }
    ],
    written: [
      { q: "On which date did the Dandi March end, and in which year?", a: "The Dandi March ended on 6 April 1930.", marks: 1 },
      { q: "What is satyagraha?", a: "Satyagraha is Gandhi's method of non-violent resistance based on truth.", marks: 1 },
      { q: "Why was the Rowlatt Act disliked, and which tragic event followed it in Amritsar?", a: "1. It allowed people to be held without a fair trial, so Indians saw it as unjust.\n2. The Jallianwala Bagh massacre took place on 13 April 1919 in Amritsar.", marks: 2 },
      { q: "What was the Swadeshi movement? What event led to it?", a: "1. The Swadeshi movement asked people to boycott foreign goods and use Indian-made goods.\n2. It arose after the Partition of Bengal in 1905.", marks: 2 },
      { q: "State two facts about the Quit India Movement.", a: "1. It began on 8 August 1942.\n2. Its call was 'Do or Die', asking Indians to make a final effort for freedom.", marks: 2 },
      { q: "Explain how the Dandi March began the Civil Disobedience Movement.", a: "1. In 1930 Gandhi led a march from 12 March to 6 April to Dandi on the coast.\n2. There he broke the salt law, showing that an unjust law could be defied peacefully.\n3. This act started the Civil Disobedience Movement, in which many people joined in non-violent protest.", marks: 3 },
      { q: "Trace three stages of the national movement from 1885 to 1947 in time order.", a: "1. 1885: the Indian National Congress was founded, and in 1905 the Partition of Bengal led to the Swadeshi movement.\n2. 1915-1930: Gandhi returned, led the Non-Cooperation Movement (1920-22), and the Congress demanded Purna Swaraj in 1929, followed by the Dandi March in 1930.\n3. 1942-1947: the Quit India Movement began in 1942 and India became independent on 15 August 1947.", marks: 3 },
      { q: "Case study: Aman visited a museum on the freedom struggle. One board showed a march of many people walking towards the sea to make salt. Another showed a crowd gathered in an enclosed garden in Amritsar in 1919. A third showed a poster with the words 'Do or Die'.\n(i) Name the march shown on the first board and the year.\n(ii) Name the event of the second board.\n(iii) Which movement does the poster belong to, and in which year did it begin?", a: "(i) The Dandi March (Salt March) of 1930.\n(ii) The Jallianwala Bagh massacre, 13 April 1919.\n(iii) The Quit India Movement, which began on 8 August 1942.", marks: 4, type: "case" }
    ]
  },
  "a-journey-through-indian-architecture": {
    mcq: [
      { q: "A stupa is best described as a", options: ["rock-cut cave temple", "dome-shaped Buddhist monument", "tall tower of a mosque", "fort with high walls"], answer: 1, explain: "A stupa is a domed Buddhist monument, such as the one at Sanchi. A tall slender tower of a mosque is a minaret.", level: 1 },
      { q: "Ajanta and Ellora are famous for their", options: ["glass palaces", "stone forts", "rock-cut caves", "iron pillars"], answer: 2, explain: "Ajanta and Ellora have caves carved out of solid rock.", level: 1 },
      { q: "The Gol Gumbaz is a famous monument at", options: ["Agra", "Thanjavur", "Konark", "Bijapur"], answer: 3, explain: "The Gol Gumbaz is at Bijapur and is known for its huge dome. Agra has the Taj Mahal and Thanjavur has the Brihadeeswara Temple.", level: 1 },
      { q: "The Victoria Memorial and the Gateway of India belong to which style?", options: ["Indo-Saracenic", "Harappan", "Dravida", "Rock-cut"], answer: 0, explain: "These colonial-era buildings blend European and Indian features, a style called Indo-Saracenic.", level: 1 },
      { q: "A minaret is a", options: ["domed roof", "rounded arch", "gateway of a temple", "tall slender tower, usually part of a mosque"], answer: 3, explain: "A minaret is a tall slender tower usually attached to a mosque. A dome is the rounded roof.", level: 1 },
      { q: "Which feature shows that Harappan cities were carefully planned?", options: ["Streets laid out in a grid with drains", "Huge rock-cut caves", "Tall minarets", "Domes with arches"], answer: 0, explain: "Harappan cities such as Mohenjo-daro had grid-like streets and drains. Caves, minarets and domes belong to later periods.", level: 2 },
      { q: "A temple in Tamil Nadu has a tall pyramid-shaped tower and towering gateways.\nWhich style is this?", options: ["Nagara", "Indo-Saracenic", "Dravida", "Stupa style"], answer: 2, explain: "Towering gateways and a pyramid-shaped tower are common in the Dravida style of the south. The Nagara style is found in the north.", level: 2 },
      { q: "Rohan sees a building with a large dome, pointed arches and tall slender towers at its corners.\nWhich tradition does it most likely belong to?", options: ["Harappan town planning", "Indo-Islamic architecture", "Rock-cut Buddhist architecture", "Dravida temple style"], answer: 1, explain: "Arches, domes and minarets are the typical features of Indo-Islamic buildings such as the Qutb Minar and the Red Fort.", level: 2 },
      { q: "Assertion (A): The Kailasa temple at Ellora is a marvel of rock-cut architecture.\nReason (R): It was carved out of a single rock instead of being built from separate pieces of stone.", options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."], answer: 0, explain: "Both are true. The remarkable thing about the Kailasa temple is that it was cut out of one rock, which is why it is called a marvel of rock-cut architecture.", level: 2, keepOrder: true },
      { q: "On a map of India, in which state do the Ajanta and Ellora caves lie?", options: ["Tamil Nadu", "Odisha", "Madhya Pradesh", "Maharashtra"], answer: 3, explain: "Ajanta and Ellora are in Maharashtra. Konark is in Odisha and the Khajuraho temples are in Madhya Pradesh.", level: 2 },
      { q: "Which set contains only Indo-Islamic monuments?", options: ["Qutb Minar, Gol Gumbaz, Red Fort", "Qutb Minar, Sanchi stupa, Red Fort", "Gol Gumbaz, Brihadeeswara Temple, Taj Mahal", "Red Fort, Konark Sun Temple, Qutb Minar"], answer: 0, explain: "The Qutb Minar, Gol Gumbaz and Red Fort are Indo-Islamic. The Sanchi stupa is Buddhist and the Brihadeeswara and Konark temples are Hindu temples.", level: 3 },
      { q: "A visitor sees a famous Dravida temple built about the year 1010 at Thanjavur.\nWhich king and dynasty built it?", options: ["Shah Jahan of the Mughals", "Rajaraja I of the Cholas", "Ashoka of the Mauryas", "Sawai Jai Singh II of Jaipur"], answer: 1, explain: "The Brihadeeswara Temple at Thanjavur was built by the Chola king Rajaraja I and finished around 1010.", level: 3 },
      { q: "Why do colonial buildings like the Victoria Memorial count as Indo-Saracenic?", options: ["They are built only of rock cut from caves", "They copy the Harappan grid plan", "They mix European features with Indian and Islamic features", "They have no domes or arches"], answer: 2, explain: "Indo-Saracenic buildings blend European design with Indian and Islamic features such as domes and arches.", level: 3 },
      { q: "Which statement about the Taj Mahal is correct?", options: ["It is a Buddhist stupa at Sanchi", "It was built by Rajaraja I at Thanjavur", "It is a rock-cut cave at Ellora", "It was built by Shah Jahan at Agra in memory of Mumtaz Mahal"], answer: 3, explain: "Shah Jahan built the Taj Mahal at Agra in memory of Mumtaz Mahal. It is an Indo-Islamic monument with a dome, arches and minarets.", level: 3 }
    ],
    written: [
      { q: "Name the temple at Ellora that was carved from a single rock.", a: "The Kailasa temple.", marks: 1 },
      { q: "What is meant by rock-cut architecture?", a: "It means buildings or temples carved out of solid rock, as at Ajanta and Ellora.", marks: 1 },
      { q: "Name two features of Harappan town planning.", a: "1. Streets were laid out in a grid pattern.\n2. Cities had drains, and public structures like the Great Bath at Mohenjo-daro.", marks: 2 },
      { q: "Write two differences between the Nagara and Dravida temple styles.", a: "1. The Nagara style is found mainly in the north, while the Dravida style is found in the south.\n2. Dravida temples are known for towering gateways and a pyramid-shaped tower.", marks: 2 },
      { q: "What is the Indo-Saracenic style? Give one example.", a: "1. It is a colonial-era style that blends European features with Indian and Islamic ones.\n2. Examples are the Victoria Memorial and the Gateway of India.", marks: 2 },
      { q: "Describe three features of Indo-Islamic architecture with one example of a monument.", a: "1. It combined Indian and Persian features.\n2. Arches, domes and minarets are typical.\n3. Examples include the Qutb Minar, Red Fort, Gol Gumbaz and the Taj Mahal.", marks: 3 },
      { q: "Write about the Brihadeeswara Temple at Thanjavur and name two other famous temples from the chapter with their locations.", a: "1. The Brihadeeswara Temple was built by the Chola king Rajaraja I and finished around 1010.\n2. The Konark Sun Temple in Odisha is shaped like a chariot.\n3. The Khajuraho temples in Madhya Pradesh are famous for their sculpture.", marks: 3 },
      { q: "Case study: During a school trip Meera first sat in front of a large dome-shaped Buddhist monument at Sanchi. Next day she went to a town in the Deccan and saw a huge dome on a building at Bijapur. She also learnt that in Mumbai the Gateway of India was built in the colonial period.\n(i) What is the Sanchi monument called?\n(ii) Name the monument at Bijapur with the huge dome.\n(iii) Which style mixes European and Indian features, as in the Gateway of India?", a: "(i) A stupa.\n(ii) The Gol Gumbaz.\n(iii) The Indo-Saracenic style.", marks: 4, type: "case" }
    ]
  },
  "the-role-of-the-judiciary-in-our-society": {
    mcq: [
      { q: "The Chief Justice of India is the head of the", options: ["Lok Sabha", "High Court of a state", "Supreme Court", "District Court"], answer: 2, explain: "The Chief Justice of India heads the Supreme Court, which is in New Delhi.", level: 1 },
      { q: "How many levels of courts does India's integrated judiciary have?", options: ["Two", "Five", "Four", "Three"], answer: 3, explain: "There are three levels: the Supreme Court, High Courts, and district and lower courts.", level: 1 },
      { q: "Which court works at the state level?", options: ["High Court", "Supreme Court", "Lok Adalat only", "Parliament"], answer: 0, explain: "Each state, or group of states, has a High Court. The Supreme Court is the single apex court for the whole country.", level: 1 },
      { q: "A dispute over a family's land is usually a", options: ["criminal case", "civil case", "case of treason", "case of judicial review"], answer: 1, explain: "Disputes about property, contracts and family matters are civil cases. Offences such as theft are criminal cases.", level: 1 },
      { q: "Lok Adalats are meant to", options: ["make laws for the states", "choose judges by election", "settle disputes quickly and at low cost", "conduct the Census"], answer: 2, explain: "Lok Adalats help ordinary people settle disputes quickly and cheaply, which improves access to justice.", level: 1 },
      { q: "What does judicial review allow courts to do?", options: ["Declare a law invalid if it goes against the Constitution", "Pass new laws for Parliament", "Appoint the Prime Minister", "Collect taxes"], answer: 0, explain: "Through judicial review the courts can examine laws and actions and strike down those that violate the Constitution.", level: 2 },
      { q: "A farmer in a village thinks his Fundamental Right has been violated.\nWhere can he go for protection?", options: ["Only to the Election Commission", "To a High Court or the Supreme Court", "To the Lok Sabha", "To the municipal corporation"], answer: 1, explain: "A person whose Fundamental Rights are violated can approach a High Court or the Supreme Court (Article 32 for the Supreme Court).", level: 2 },
      { q: "Why are judges not elected like ministers?", options: ["Because they do not need to know the law", "Because elected judges would have to follow their voters", "So they can decide fairly without depending on votes or pressure", "Because courts cannot hear civil cases"], answer: 2, explain: "Judges are not elected so that they can decide cases fairly, free from political pressure and without having to please voters.", level: 2 },
      { q: "A village school is closed because the building is unsafe, and children have nowhere to study. A group of citizens writes to a High Court on behalf of the children.\nWhat is this kind of petition called?", options: ["Judicial review", "A civil suit between two neighbours", "A criminal trial", "Public Interest Litigation"], answer: 3, explain: "A petition filed for a matter of public concern, on behalf of people who cannot easily approach the court, is a Public Interest Litigation (PIL).", level: 2 },
      { q: "Assertion (A): An independent judiciary is necessary in a democracy.\nReason (R): It allows judges to decide cases on the basis of the law and the Constitution, without pressure from the government.", options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."], answer: 0, explain: "Both are true. Fair decisions without pressure are exactly why independence matters, so R explains A.", level: 2, keepOrder: true },
      { q: "Which arrangement lists the courts from the highest to the lowest?", options: ["High Court, Supreme Court, District Court", "District Court, High Court, Supreme Court", "Supreme Court, District Court, High Court", "Supreme Court, High Court, District Court"], answer: 3, explain: "The Supreme Court is at the top, then the High Courts in the states, then the district and lower courts.", level: 3 },
      { q: "A state law takes away a right guaranteed by the Constitution, and a court strikes it down.\nWhich power has the court used, and which principle does it protect?", options: ["Judicial review, protecting the supremacy of the Constitution", "Making laws, protecting the state government", "Election of judges, protecting voters", "Police power, protecting property"], answer: 0, explain: "Declaring a law invalid because it violates the Constitution is judicial review. It shows that the Constitution is above ordinary laws.", level: 3 },
      { q: "Which feature helps judges work without fear or favour?", options: ["They are chosen in every general election", "Their salaries are protected and removal needs a special process in Parliament", "They can be transferred by a minister at will", "They take orders from the Prime Minister"], answer: 1, explain: "Protected salaries and a special, difficult process for removal keep judges secure, so they can decide freely.", level: 3 },
      { q: "A person in a remote area cannot afford a lawyer and a long court case. Which step best improves his access to justice?", options: ["Avoid all legal matters", "Settle only by paying the other party", "Wait for the case to end by itself", "Use legal aid or take the matter to a Lok Adalat"], answer: 3, explain: "Legal aid and Lok Adalats are meant to make justice more affordable and quicker for ordinary people.", level: 3 }
    ],
    written: [
      { q: "Which is the highest court in India and where is it located?", a: "The Supreme Court, located in New Delhi.", marks: 1 },
      { q: "Give one example each of a civil case and a criminal case.", a: "A dispute over property is a civil case; theft is a criminal case.", marks: 1 },
      { q: "Name the three levels of courts in India.", a: "1. The Supreme Court at the top.\n2. High Courts in the states.\n3. District and lower (subordinate) courts.", marks: 2 },
      { q: "What is judicial review? Why is it important?", a: "1. It is the power of courts to examine laws and actions and declare invalid those that go against the Constitution.\n2. It protects the Constitution and the rights of citizens from misuse of power.", marks: 2 },
      { q: "What is a Public Interest Litigation (PIL)?", a: "1. It is a case brought to court for a matter of public concern.\n2. Any person or group may file it on behalf of people who cannot approach the court themselves.", marks: 2 },
      { q: "Explain three functions of the judiciary.", a: "1. It settles disputes between people, between people and the government, and between governments.\n2. It interprets the Constitution and the laws and can use judicial review.\n3. It protects the Fundamental Rights of citizens.", marks: 3 },
      { q: "Why is an independent judiciary important? Mention three ways in which independence is protected or helps.", a: "1. Judges can decide fairly without pressure from the government or anyone else.\n2. Judges are not elected and cannot be removed easily; removal needs a special process in Parliament.\n3. Their salaries are protected, so they can work without fear or favour.", marks: 3 },
      { q: "Case study: Sunita's neighbours argue about a boundary wall between their houses. In another town, a shop has been robbed. A group of villagers also writes to a court because the only well in their village has become polluted and everyone is falling ill.\n(i) What type of case is the boundary dispute?\n(ii) What type of case is the robbery?\n(iii) Under which arrangement can the villagers approach the court for the whole village?", a: "(i) A civil case, since it is about property.\n(ii) A criminal case, since robbery is an offence.\n(iii) By filing a Public Interest Litigation (PIL), as the matter is of public concern.", marks: 4, type: "case" }
    ]
  },
  "citizenship-rights-and-duties": {
    mcq: [
      { q: "A person who is not a citizen of India is called", options: ["an alien", "a native", "a voter", "a member of Parliament"], answer: 0, explain: "A person who is not a citizen of a country is an alien or foreigner there.", level: 1 },
      { q: "India has", options: ["citizenship of each state", "double citizenship", "single citizenship", "no citizenship law"], answer: 2, explain: "India has single citizenship: a person is a citizen of India, not of a particular state.", level: 1 },
      { q: "Which Fundamental Right protects people from forced labour?", options: ["Right to Equality", "Right against Exploitation", "Right to Freedom of Religion", "Cultural and Educational Rights"], answer: 1, explain: "The Right against Exploitation prohibits forced labour, trafficking and the employment of young children in hazardous work.", level: 1 },
      { q: "The Right to Education for children aged 6 to 14 is part of which article?", options: ["Article 14", "Article 32", "Article 51A", "Article 21A"], answer: 3, explain: "Article 21A makes education a Fundamental Right for children aged 6 to 14. Article 32 is the right to approach the Supreme Court.", level: 1 },
      { q: "Which Fundamental Right can be used to approach the Supreme Court if other rights are violated?", options: ["Right to Constitutional Remedies", "Right to Equality", "Right to Freedom", "Right to Religion"], answer: 0, explain: "The Right to Constitutional Remedies (Article 32) lets a person go to the courts to enforce Fundamental Rights.", level: 1 },
      { q: "Which of these is NOT a way of acquiring Indian citizenship under the Citizenship Act, 1955?", options: ["Birth", "Descent", "Registration", "Owning a house in India"], answer: 3, explain: "The Act lists birth, descent, registration and naturalisation. Owning property does not give citizenship.", level: 2 },
      { q: "How are Fundamental Rights different from Directive Principles?", options: ["Directive Principles can be enforced in court, rights cannot", "Fundamental Rights can be enforced in court, Directive Principles cannot", "Both can be enforced in court", "Neither guides the government"], answer: 1, explain: "Fundamental Rights are enforceable in courts. Directive Principles only guide the government in making policy.", level: 2 },
      { q: "Karan paints slogans on the wall of a public school.\nWhich Fundamental Duty is he failing to follow?", options: ["Respecting the national anthem", "Developing scientific temper", "Protecting public property", "Promoting harmony"], answer: 2, explain: "A school is public property, and citizens have a duty to protect it. Damaging it goes against this duty.", level: 2 },
      { q: "Assertion (A): Fundamental Rights have reasonable limits.\nReason (R): One person's use of a right should not harm the rights of others.", options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."], answer: 0, explain: "Both are true. Limits exist so that rights can be enjoyed by all, which is exactly what R states.", level: 2, keepOrder: true },
      { q: "A factory keeps 12-year-old Dev working long hours in a dangerous job.\nWhich Fundamental Right is being denied to him?", options: ["Right to vote", "Right to Constitutional Remedies", "Right against Exploitation", "Right to Equality in public jobs"], answer: 2, explain: "Employing young children in hazardous work is prohibited under the Right against Exploitation.", level: 2 },
      { q: "Fundamental Duties were added to the Constitution by which amendment, and in which year?", options: ["42nd Amendment, 1976", "86th Amendment, 1950", "42nd Amendment, 1950", "44th Amendment, 1976"], answer: 0, explain: "Fundamental Duties were added by the 42nd Amendment in 1976. There are 11 of them at present.", level: 3 },
      { q: "Which statement shows that rights and duties go together?", options: ["Only rich people have duties", "Duties are for officials; rights are for citizens", "Rights stop mattering once duties are known", "If everyone respects the rights of others, everyone can enjoy their own rights"], answer: 3, explain: "A right can be enjoyed by all only if each person respects others' rights and does their duties.", level: 3 },
      { q: "Zara was born in India to Indian parents. Her friend Liam, a foreign national, lived in India for the period required by law and was then granted citizenship.\nBy which ways did they get citizenship?", options: ["Zara by birth, Liam by registration only", "Zara by naturalisation, Liam by birth", "Zara by birth, Liam by naturalisation", "Both by descent"], answer: 2, explain: "Zara became a citizen by birth. Liam got citizenship after living in the country for the prescribed period, which is naturalisation.", level: 3 },
      { q: "A court is asked to order the government to follow a Directive Principle.\nWhat is the likely position?", options: ["The court must enforce it like a Fundamental Right", "The court cannot enforce it, since Directive Principles are not enforceable in courts", "The court must cancel the Constitution", "The court must hold an election"], answer: 1, explain: "Directive Principles guide the government but cannot be enforced in court, unlike Fundamental Rights.", level: 3 }
    ],
    written: [
      { q: "Name any two Fundamental Rights.", a: "Any two of: Right to Equality, Right to Freedom, Right against Exploitation, Right to Freedom of Religion, Cultural and Educational Rights, Right to Constitutional Remedies.", marks: 1 },
      { q: "Who is a citizen?", a: "A citizen is a full member of a country, with legal rights and duties.", marks: 1 },
      { q: "In what four ways can citizenship be acquired in India?", a: "1. By birth and by descent.\n2. By registration and by naturalisation.", marks: 2 },
      { q: "What is meant by single citizenship? Why is it important?", a: "1. Every person is a citizen of India and not of a separate state.\n2. It helps to keep the country united, giving the same status to all citizens.", marks: 2 },
      { q: "Name two Fundamental Duties of a citizen.", a: "1. Respecting the Constitution, the national flag and the national anthem.\n2. Protecting public property and safeguarding the environment (or any other listed duty).", marks: 2 },
      { q: "Explain how rights and duties are connected.", a: "1. Rights give each citizen freedoms and protection.\n2. Duties ask citizens to respect the Constitution and the rights of others.\n3. Rights can be enjoyed by all only when everyone also performs duties.", marks: 3 },
      { q: "Compare Fundamental Rights and Directive Principles in three points.", a: "1. Fundamental Rights are guaranteed to citizens; Directive Principles guide the government in making policy.\n2. Fundamental Rights can be enforced in a court.\n3. Directive Principles cannot be enforced in a court.", marks: 3 },
      { q: "Case study: In Meera's colony the residents decide to plant trees along the road, but one neighbour dumps his waste in the open ground nearby. Meera's class also learns that all children aged 6 to 14 have a right to free education.\n(i) Which Fundamental Duty do the tree-planters follow?\n(ii) Which duty is the neighbour ignoring?\n(iii) Under which article is education for children aged 6 to 14 a right?", a: "(i) The duty to safeguard the environment.\n(ii) The duty to protect and improve the natural environment, since dumping waste in the open harms it.\n(iii) Article 21A.", marks: 4, type: "case" }
    ]
  },
  "dynamics-of-population": {
    mcq: [
      { q: "What does a Census do?", options: ["Counts the population and collects details about people", "Elects the government", "Measures rainfall", "Prints currency"], answer: 0, explain: "The Census is a count of the whole population along with details about people. In India it is held every ten years.", level: 1 },
      { q: "Population density is the number of people living in", options: ["each house", "each state", "each square kilometre", "each village group"], answer: 2, explain: "Density is people per square kilometre.", level: 1 },
      { q: "Which area of India has a very high population density?", options: ["Thar Desert", "Northern Plains", "High Himalayan peaks", "Thick forests of the north-east hills"], answer: 1, explain: "The flat, fertile Northern Plains with plenty of water support many people. Deserts, high mountains and dense forests have few.", level: 1 },
      { q: "The sex ratio is the number of", options: ["males per 1000 females", "females per 100 males", "children per 1000 adults", "females per 1000 males"], answer: 3, explain: "In India the sex ratio is counted as females per 1000 males.", level: 1 },
      { q: "A population pyramid shows", options: ["people in each age group, divided by gender", "only the number of migrants", "rainfall over a year", "the height of a country's mountains"], answer: 0, explain: "A population pyramid shows how many males and females are in each age group.", level: 1 },
      { q: "In a village, 20 children are born and 8 people die in a year per 1000 people.\nWhat is the natural growth rate per 1000?", options: ["28", "10", "12", "160"], answer: 2, explain: "Natural growth = birth rate − death rate = 20 − 8 = 12 per 1000.", level: 2 },
      { q: "A town has 24,000 people living in an area of 80 sq km.\nWhat is its population density?", options: ["200 per sq km", "300 per sq km", "400 per sq km", "1,920,000 per sq km"], answer: 1, explain: "Density = 24,000 ÷ 80 = 300 people per sq km.", level: 2 },
      { q: "A district has 5,00,000 males and 4,70,000 females.\nWhat is its sex ratio?", options: ["940", "1,064", "530", "970"], answer: 0, explain: "Sex ratio = females per 1000 males = 4,70,000 ÷ 5,00,000 × 1000 = 940.", level: 2 },
      { q: "Assertion (A): A large working-age population can become a demographic dividend.\nReason (R): It helps only when people are healthy, educated and employed.", options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."], answer: 0, explain: "Both are true. A big working-age group brings benefits only if people have health, skills and jobs, so R explains when A holds.", level: 2, keepOrder: true },
      { q: "Ramesh moves from a flood-hit village to a city for a good job.\nWhich is a push factor and which is a pull factor?", options: ["Job is push, flood is pull", "Both are push factors", "Flood is push, job is pull", "Both are pull factors"], answer: 2, explain: "The flood drove him away from the village, a push factor. The better job attracted him to the city, a pull factor.", level: 2 },
      { q: "Town A has 9,000 people in 30 sq km. Town B has 12,000 people in 20 sq km.\nWhich statement is correct?", options: ["Town A is denser, with 300 per sq km against 600", "Both have the same density", "Town B is denser, with 600 per sq km against 300", "Density cannot be calculated"], answer: 2, explain: "A: 9,000 ÷ 30 = 300. B: 12,000 ÷ 20 = 600. So B is denser.", level: 3 },
      { q: "A country's death rate falls sharply but its birth rate stays high.\nWhat will most likely happen to its population?", options: ["It will fall quickly", "It will grow faster", "It will stay exactly the same", "It will stop being counted"], answer: 1, explain: "Natural growth is birth rate minus death rate. If deaths fall and births stay high, the difference grows, so population increases faster.", level: 3 },
      { q: "On a population map of India, which pair is correctly matched?", options: ["Thar Desert - high density", "Himalayan peaks - high density", "Dense forests - high density", "Ganga plain - high density"], answer: 3, explain: "The Ganga plain is flat, fertile and well watered, so it is densely populated. The desert, high mountains and dense forests are sparsely populated.", level: 3 },
      { q: "Which is the best example of people being a resource?", options: ["Young people who are healthy, skilled and employed", "People who have no education or health care", "People forced to leave their homes by flood", "A large population that has no jobs"], answer: 0, explain: "People become a resource when they have good health, education and skills.", level: 3 }
    ],
    written: [
      { q: "How often is the Census held in India?", a: "Every ten years.", marks: 1 },
      { q: "Define migration.", a: "Migration is the movement of people from one place to another to live.", marks: 1 },
      { q: "Name two reasons for migration.", a: "1. Jobs and education.\n2. Marriage or disaster (any two reasons).", marks: 2 },
      { q: "A district has 4,50,000 females and 5,00,000 males. Find its sex ratio.", a: "1. Sex ratio = females per 1000 males.\n2. = 4,50,000 ÷ 5,00,000 × 1000 = 900.", marks: 2 },
      { q: "What is natural growth rate? If the birth rate is 25 and the death rate is 9 per 1000, find it.", a: "1. Natural growth rate = birth rate − death rate.\n2. = 25 − 9 = 16 per 1000.", marks: 2 },
      { q: "Why is population unevenly distributed in India? Give three reasons.", a: "1. Flat, fertile land such as the Northern Plains attracts people.\n2. Availability of water and a moderate climate support settlement and farming.\n3. Mountains, deserts and dense forests are difficult to live in, so they have few people.", marks: 3 },
      { q: "A town has 1,20,000 people and an area of 400 sq km. Find its density. How does it compare with India's 2011 density of about 382 per sq km?", a: "1. Density = 1,20,000 ÷ 400 = 300 people per sq km.\n2. 300 is lower than 382.\n3. So the town is less densely populated than India's average.", marks: 3 },
      { q: "Case study: In 2011 India's population was about 121 crore, with a sex ratio of about 943 and a literacy rate of about 74%. Rohit says that a large population is a problem, while Ayesha says that educated, healthy and employed people can be a strength.\n(i) What is the 2011 sex ratio and what does it mean?\n(ii) What name is given to the benefit of a large working-age population?\n(iii) Whose view is closer to the idea of 'people as a resource', and why?", a: "(i) About 943, meaning there were about 943 females for every 1000 males.\n(ii) Demographic dividend.\n(iii) Ayesha's, because people become a resource when they have good health, education and skills.", marks: 4, type: "case" }
    ]
  },
  "indias-urban-landscape": {
    mcq: [
      { q: "A city with a population of 10 lakh or more is called a", options: ["statutory town", "million-plus city", "census village", "ward"], answer: 1, explain: "Cities with 10 lakh or more people are called million-plus cities.", level: 1 },
      { q: "Which body looks after water supply, roads and waste disposal in a large city?", options: ["Gram Panchayat", "Supreme Court", "Municipal Corporation", "Election Commission"], answer: 2, explain: "Municipal corporations and municipalities provide basic civic services in cities.", level: 1 },
      { q: "Jaipur was planned in the 18th century by", options: ["Sawai Jai Singh II", "Rajaraja I", "Shah Jahan", "Akbar"], answer: 0, explain: "Jaipur was planned by Sawai Jai Singh II. Chandigarh was planned after Independence.", level: 1 },
      { q: "Which of these is a planned city built after Independence?", options: ["Varanasi", "Chandigarh", "Old Delhi", "Mohenjo-daro"], answer: 1, explain: "Chandigarh was planned after Independence. Mohenjo-daro was an ancient planned city.", level: 1 },
      { q: "A slum is a settlement with", options: ["wide parks", "wealthy residents", "plenty of space", "crowded housing and few basic services"], answer: 3, explain: "A slum is a crowded settlement with poor housing and few basic services.", level: 1 },
      { q: "Which is a minimum condition for a census town?", options: ["At least 75% of male workers in non-farm jobs", "A population above one crore", "A port on the coast", "An old fort"], answer: 0, explain: "A census town needs at least 5000 people, at least 400 per sq km and at least 75% of male workers in non-farm jobs.", level: 2 },
      { q: "A settlement has 6,000 people, a density of 450 per sq km and 80% of its male workers in non-farm jobs.\nWhat is it called?", options: ["A forest village", "A census town", "A million-plus city", "A hamlet"], answer: 1, explain: "It meets all three census-town conditions: at least 5000 people, at least 400 per sq km and at least 75% non-farm male workers.", level: 2 },
      { q: "Why did many cities grow near rivers and ports?", options: ["No one lives near water", "Rivers and ports made farming impossible", "These places had water, trade and transport", "Governments banned inland cities"], answer: 2, explain: "Rivers and ports gave water, transport and trade, which attract people and industry.", level: 2 },
      { q: "Assertion (A): Many people from villages move to cities.\nReason (R): Cities offer more jobs, education and healthcare.", options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."], answer: 0, explain: "Both are true. Better opportunities in cities pull people from villages, so R explains A.", level: 2, keepOrder: true },
      { q: "A city's roads are jammed every evening and the air is dirty.\nWhich step would help most?", options: ["Allow more private vehicles only", "Remove all green spaces", "Stop collecting waste", "Better public transport and more green spaces"], answer: 3, explain: "Better public transport reduces traffic and pollution, and green spaces improve air quality.", level: 2 },
      { q: "Settlement X has 3,500 people, density 600 per sq km and 90% non-farm male workers.\nWhy is it not a census town?", options: ["Its density is too high", "It has too many non-farm workers", "Its population is below 5000", "It has no municipality"], answer: 2, explain: "A census town needs at least 5000 people. X meets the density and workers conditions but not the size condition.", level: 3 },
      { q: "On a map, Mumbai lies on the Arabian Sea coast and Kolkata on the Hooghly river.\nWhat common reason explains the growth of both?", options: ["Both are far from water", "Both are in deserts", "Both are in hills", "Both had water routes helping trade"], answer: 3, explain: "Port and river locations made trade and transport easy, helping the cities grow.", level: 3 },
      { q: "Which pair shows how villages and cities depend on each other?", options: ["Villages supply food and raw materials; cities provide goods and services", "Cities supply food; villages supply cars", "Cities need nothing from villages", "Villages need no services"], answer: 0, explain: "Villages supply food and raw materials, while cities provide goods and services. Each needs the other.", level: 3 },
      { q: "A city's population doubles in 20 years but its housing is not increased.\nWhich problem is most likely to grow?", options: ["Fewer slums", "Falling traffic", "Overcrowding and slums", "Less pollution"], answer: 2, explain: "More people without more housing leads to overcrowding and slums.", level: 3 }
    ],
    written: [
      { q: "Define urbanisation.", a: "Urbanisation is the increase in the share of people living in towns and cities.", marks: 1 },
      { q: "Name one city planned after Independence.", a: "Chandigarh.", marks: 1 },
      { q: "What are statutory towns?", a: "1. Towns with a municipality, corporation or similar body.\n2. They are notified by law.", marks: 2 },
      { q: "Give two reasons why cities grow.", a: "1. Industry, trade and services create jobs.\n2. Migration from villages adds to the population; many cities also grew around rivers, ports and trade routes.", marks: 2 },
      { q: "State the three conditions for a census town.", a: "1. At least 5000 people.\n2. A density of at least 400 per sq km, and at least 75% of male workers in non-farm jobs.", marks: 2 },
      { q: "Describe three problems faced by fast-growing cities.", a: "1. Overcrowding and a shortage of housing, leading to slums.\n2. Traffic congestion and air pollution.\n3. Waste disposal and pressure on water and other services.", marks: 3 },
      { q: "Suggest three ways of making cities better places to live.", a: "1. Improve public transport.\n2. Add green spaces and recycle waste.\n3. Provide affordable housing and plan for growth.", marks: 3 },
      { q: "Case study: Neha's family moved from a village to a million-plus city where her father got a factory job. The city has good schools and hospitals, but their rented room is crowded and the roads are jammed.\n(i) Name the type of factor that drew the family to the city.\n(ii) What does 'million-plus' mean?\n(iii) Mention one problem Neha faces and one possible solution.", a: "(i) A pull factor (better jobs, schools and healthcare).\n(ii) A city with a population of 10 lakh or more.\n(iii) Problem: crowded housing or traffic. Solution: affordable housing or better public transport.", marks: 4, type: "case" }
    ]
  },
  "cultural-currents-13th-to-17th-centuries": {
    mcq: [
      { q: "Bhakti saints stressed", options: ["rigid social divisions", "personal devotion to God", "only temple rituals", "use of Sanskrit alone"], answer: 1, explain: "The Bhakti movement stressed loving, personal devotion and rejected rigid social divisions.", level: 1 },
      { q: "Which poet's two-line verses are called dohas?", options: ["Tansen", "Amir Khusrau", "Kabir", "Mirabai"], answer: 2, explain: "Kabir's dohas are famous. A doha is a two-line verse.", level: 1 },
      { q: "Guru Nanak lived from", options: ["1469 to 1539", "1200 to 1260", "1600 to 1670", "1750 to 1800"], answer: 0, explain: "Guru Nanak (1469-1539) preached one God, equality, honest work and sharing.", level: 1 },
      { q: "Which musician is linked with Akbar's court?", options: ["Kabir", "Namdev", "Tukaram", "Tansen"], answer: 3, explain: "Tansen was a famous musician at Akbar's court.", level: 1 },
      { q: "Ramcharitmanas was written in which language?", options: ["Awadhi", "Persian", "Tamil", "English"], answer: 0, explain: "Tulsidas wrote the Ramcharitmanas in Awadhi.", level: 1 },
      { q: "Why did Bhakti saints compose songs in local languages?", options: ["Because only scholars could read them", "So that ordinary people could understand the message", "Because they disliked music", "Because kings ordered it"], answer: 1, explain: "Local languages let common people understand and join in the devotion.", level: 2 },
      { q: "A langar serves food to everyone sitting together.\nWhich idea does it express?", options: ["Fixed rank by birth", "Profit from food", "Equality and service", "Fasting only"], answer: 2, explain: "Langar, started by Guru Nanak, promotes equality and service as all eat together.", level: 2 },
      { q: "Sufi gatherings were known for", options: ["love, tolerance and music such as qawwali", "war and conquest", "taxes", "silence only"], answer: 0, explain: "Sufi saints preached love, tolerance and service, and music like qawwali was part of their gatherings.", level: 2 },
      { q: "Assertion (A): Many Bhakti saints are remembered across communities.\nReason (R): They taught love of God and equality, and spoke in the people's language.", options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."], answer: 0, explain: "Both are true. Their message of love and equality in everyday language reached all, so R explains A.", level: 2, keepOrder: true },
      { q: "On a map, Ajmer is linked with which Sufi saint?", options: ["Baba Farid", "Nizamuddin Auliya", "Tulsidas", "Khwaja Moinuddin Chishti"], answer: 3, explain: "Khwaja Moinuddin Chishti is linked with Ajmer. Nizamuddin Auliya is linked with Delhi.", level: 2 },
      { q: "A tourist visits Hampi, once the Vijayanagara capital, and Fatehpur Sikri near Agra.\nWhich statement about the period's buildings is correct?", options: ["No arches", "Only wooden roofs", "A blend of Indian and Persian features at Fatehpur Sikri, and rich art at Hampi", "Only glass buildings"], answer: 2, explain: "Fatehpur Sikri combined Indian and Persian features, and Hampi's monuments show the cultural richness of Vijayanagara.", level: 3 },
      { q: "Which pair is correctly matched?", options: ["Tulsidas - Ramcharitmanas", "Guru Nanak - Qawwali", "Amir Khusrau - Langar", "Tansen - Dohas"], answer: 0, explain: "Tulsidas wrote the Ramcharitmanas. Langar was begun by Guru Nanak, and Kabir is famed for dohas.", level: 3 },
      { q: "Why do Bhakti and Sufi traditions show a shared cultural life?", options: ["Both ended all music", "Both stressed love, tolerance and service to others", "Both avoided local languages", "Both were ruled by one king"], answer: 1, explain: "Both traditions preached love and service, and encouraged people from different backgrounds to come together.", level: 3 },
      { q: "Which activity best shows royal patronage of the arts in this period?", options: ["Closing all courts", "Banning poetry", "Mughal rulers supporting miniature painters", "Stopping trade"], answer: 2, explain: "Mughal rulers supported miniature painting, and many kingdoms supported scholars, artists and poets.", level: 3 }
    ],
    written: [
      { q: "Who started the practice of langar?", a: "Guru Nanak.", marks: 1 },
      { q: "What is a miniature painting?", a: "A small, detailed painting, often made for books or royal courts.", marks: 1 },
      { q: "Name two Bhakti saints.", a: "Any two of: Kabir, Guru Nanak, Mirabai, Tulsidas, Chaitanya, Tukaram, Sankardev, Ravidas, Namdev.", marks: 2 },
      { q: "Who was Amir Khusrau? Why is he remembered?", a: "1. He was a poet and musician who wrote in Persian and Hindavi.\n2. He is linked with the growth of qawwali and Hindustani music.", marks: 2 },
      { q: "State two teachings of Guru Nanak.", a: "1. Belief in one God and equality of all people.\n2. Honest work, sharing and remembering God.", marks: 2 },
      { q: "Describe three features of the Bhakti movement.", a: "1. It stressed personal devotion to God.\n2. It rejected rigid social divisions and rituals.\n3. Saints composed songs in local languages.", marks: 3 },
      { q: "Explain the role of the Sufi saints in this period.", a: "1. Sufi saints such as Moinuddin Chishti, Nizamuddin Auliya and Baba Farid preached love and tolerance.\n2. They encouraged service to others.\n3. Music like qawwali was part of their gatherings.", marks: 3 },
      { q: "Case study: At a community fair, Zoya hears a qawwali, then a singer sings a famous two-line verse by Kabir. Later she eats a free meal at a langar where everyone sits in a row.\n(i) Which tradition is linked with qawwali?\n(ii) What is a doha?\n(iii) What value does the langar teach?", a: "(i) The Sufi tradition.\n(ii) A two-line verse in Hindi poetry.\n(iii) Equality and service.", marks: 4, type: "case" }
    ]
  }
});
